    private static boolean matches(File file,long offset,String expected) {
        try(RandomAccessFile in=new RandomAccessFile(file,"r")) {
            in.seek(offset);
            for(int i=0;i<expected.length();i+=2) if(in.read()!=Integer.parseInt(expected.substring(i,i+2),16)) return false;
            return true;
        } catch(IOException e) { return false; }
    }
    static boolean sample(File file,String path) {
        if (CacheUpdates.has(path)) return CacheUpdates.updatedSample(file, path);
        switch(path) { case "texdb/gta3/gta3.dxt.dat": return matches(file,13594362L,"bbd6f7bdae6b88eadbd638c6c7fdbf6adbd618c6eddb22bb");
case "texdb/gta3/gta3.dxt.tmb": return matches(file,176048L,"1cdf9aceb537bf7adbd679ce88fedc9efcd679ce70787fed");
case "texdb/gta_int/gta_int.dxt.dat": return matches(file,222558278L,"dbd659c6db995d26bbce39beaff3b5efbbcef8bd8ed2ee9e");
case "texdb/gta_int/gta_int.dxt.tmb": return matches(file,2347344L,"59c614a51e1e3c3c7ac6149db4b4b4b639c635a53c1c1414");
case "texdb/gta_int.img": return matches(file,415299584L,"1000000018fb0000ffff0318010000000c000000ffff0318");
case "texdb/samp.img": return matches(file,9275392L,"1000000018fb0000ffff0318010000000c000000ffff0318");
case "loader/imgs.cfg": return file.length()==35L && matches(file,0L,"6c6f616465725f736b696e0a6c6f616465725f6361720a6c6f616465725f636172730a");
case "SAMP/gta.dat": return file.length()==1533L && matches(file,0L,"") && matches(file,512L,"") && matches(file,1024L,"");
case "data/gta.dat": return file.length()==1372L && matches(file,0L,"") && matches(file,512L,"") && matches(file,1024L,""); default:return true; } }
    static boolean compatible(Map<String,WeikCache.Entry> files) {
        for(String name:new String[]{"texdb/gta3/gta3.dxt.dat","texdb/gta3/gta3.dxt.tmb","texdb/gta_int/gta_int.dxt.dat","texdb/gta_int/gta_int.dxt.tmb","texdb/gta_int.img","texdb/samp.img"}) {
            WeikCache.Entry e=files.get(name);
            if(e==null || original(e.hash)==null) return false;
        }
        return true;
    }
    public static boolean ready(String root) { if(root==null)return false; if(!sample(new File(root,"texdb/gta3/gta3.dxt.dat"),"texdb/gta3/gta3.dxt.dat")) return false;
if(!sample(new File(root,"texdb/gta3/gta3.dxt.tmb"),"texdb/gta3/gta3.dxt.tmb")) return false;
if(!sample(new File(root,"texdb/gta_int/gta_int.dxt.dat"),"texdb/gta_int/gta_int.dxt.dat")) return false;
if(!sample(new File(root,"texdb/gta_int/gta_int.dxt.tmb"),"texdb/gta_int/gta_int.dxt.tmb")) return false;
if(!sample(new File(root,"texdb/gta_int.img"),"texdb/gta_int.img")) return false;
if(!sample(new File(root,"texdb/samp.img"),"texdb/samp.img")) return false;
if(!sample(new File(root,"loader/imgs.cfg"),"loader/imgs.cfg")) return false;
if(!sample(new File(root,"SAMP/gta.dat"),"SAMP/gta.dat")) return false;
if(!sample(new File(root,"data/gta.dat"),"data/gta.dat")) return false; return true; }
